#!/home/eshort/human_sandbox/ament_ws/src/stretch4_multi_teleop/teleop_interfaces/venv_voice/bin/python3
import sys
import os
import threading
import time
import yaml
import numpy as np
import io
import re
from pynput import keyboard

# Add ROS and Workspace paths for inheritance
sys.path.append("/opt/ros/jazzy/lib/python3.12/site-packages")
sys.path.append("/home/eshort/human_sandbox/ament_ws/install/multi_teleop/lib/python3.12/site-packages")

import rclpy
from multi_teleop.base import InputInterfaceNode
import sounddevice as sd

class VoiceNode(InputInterfaceNode):
    def __init__(self):
        # We need to load the config BEFORE calling super().__init__ 
        # to know our axis/button names.
        self._commands = []
        self._axis_map = {}   # axis_name -> index
        self._button_map = {} # keyword -> index
        
        # Temporary node to read parameter
        temp_node = rclpy.create_node('temp_voice_loader')
        temp_node.declare_parameter('config_file', '')
        config_path = temp_node.get_parameter('config_file').value
        temp_node.destroy_node()

        axis_names = []
        button_names = []
        
        if config_path:
            try:
                with open(config_path, 'r') as f:
                    config = yaml.safe_load(f)
                    self._commands = config.get('voice_commands', [])
                    for cmd in self._commands:
                        if 'axis' in cmd:
                            name = cmd['axis'].lower()
                            if name not in self._axis_map:
                                self._axis_map[name] = len(axis_names)
                                axis_names.append(name)
                        elif 'keyword' in cmd:
                            name = cmd['keyword'].lower()
                            if name not in self._button_map:
                                self._button_map[name] = len(button_names)
                                button_names.append(name)
            except Exception as e:
                print(f"Failed to load voice config: {e}")

        # Fallback if config is empty
        if not axis_names and not button_names:
            axis_names = ['dummy_axis']
            button_names = ['dummy_button']

        super().__init__('voice_node', axis_names, button_names)
        
        self.declare_parameter('config_file', config_path or '')
        self.declare_parameter('model_size', 'base.en')
        
        # Audio settings
        self.CHANNELS = 1
        self.RATE = 16000
        self._frames = []
        self._is_recording = False
        
        # Whisper model
        from faster_whisper import WhisperModel
        model_size = self.get_parameter('model_size').value
        self.get_logger().info(f"Loading Whisper model: {model_size}...")
        self._model = WhisperModel(model_size, device="cpu", compute_type="int8")
        self.get_logger().info("Whisper model loaded.")
        
        # Internal state
        self._axes = [0.0] * len(axis_names)
        self._buttons = [0] * len(button_names)
        
        # PTT Listener
        self._listener = keyboard.Listener(on_press=self._on_press, on_release=self._on_release)
        self._listener.start()
        
        self.get_logger().info(f"Voice Tracker initialized with {len(axis_names)} axes and {len(button_names)} buttons. Hold SPACE to talk.")

    def _on_press(self, key):
        if key == keyboard.Key.space and not self._is_recording:
            self._is_recording = True
            self._frames = []
            threading.Thread(target=self._record_thread, daemon=True).start()
            self.get_logger().info("Recording...")

    def _on_release(self, key):
        if key == keyboard.Key.space and self._is_recording:
            self._is_recording = False
            self.get_logger().info("Stopped recording. Transcribing...")

    def _record_thread(self):
        def callback(indata, frames, time, status):
            if self._is_recording:
                self._frames.append(indata.copy())

        with sd.InputStream(samplerate=self.RATE, channels=self.CHANNELS, callback=callback):
            while self._is_recording:
                time.sleep(0.05)
        
        self._process_audio()

    def _process_audio(self):
        if not self._frames:
            return
        audio_np = np.concatenate(self._frames, axis=0).flatten()
        segments, info = self._model.transcribe(audio_np, beam_size=5)
        text = " ".join([s.text for s in segments]).lower().strip()
        self.get_logger().info(f"Transcribed: '{text}'")
        if text:
            self._parse_commands(text)

    def _parse_commands(self, text):
        updated = False
        for cmd in self._commands:
            # Handle Buttons
            if 'keyword' in cmd:
                kw = cmd['keyword'].lower()
                if kw in text:
                    action = cmd.get('action', 'tap')
                    idx = self._button_map[kw]
                    if action == 'toggle':
                        self._buttons[idx] = 1 if self._buttons[idx] == 0 else 0
                        updated = True
                    elif action == 'tap':
                        self._buttons[idx] = 1
                        self.publish_input(self._axes, self._buttons)
                        time.sleep(0.1)
                        self._buttons[idx] = 0
                        updated = True
            
            # Handle Axes
            elif 'axis' in cmd:
                name = cmd['axis'].lower()
                idx = self._axis_map[name]
                action = cmd.get('action', 'step')
                
                if action == 'step':
                    up_kw = f"{name} {cmd['up'].lower()}"
                    down_kw = f"{name} {cmd['down'].lower()}"
                    step = cmd.get('step', 0.1)
                    
                    if up_kw in text:
                        self._axes[idx] = min(1.0, self._axes[idx] + step)
                        updated = True
                    elif down_kw in text:
                        self._axes[idx] = max(-1.0, self._axes[idx] - step)
                        updated = True
                
                elif action == 'scale':
                    # Look for [axis name] [number]
                    match = re.search(rf"{re.escape(name)}\s+(.*)", text)
                    if match:
                        after_text = match.group(1).strip()
                        parts = after_text.split()
                        if not parts: continue
                        
                        multiplier = 1.0
                        num_part = parts[0]
                        if parts[0] in ['negative', 'minus', '-'] and len(parts) > 1:
                            multiplier = -1.0
                            num_part = parts[1]
                        elif parts[0].startswith('-'):
                            num_part = parts[0]
                        
                        val = self._word_to_num(num_part)
                        if val is not None:
                            v_min = cmd['min']
                            v_max = cmd['max']
                            real_val = val * multiplier
                            norm_val = 2 * (real_val - v_min) / (v_max - v_min) - 1
                            self._axes[idx] = max(-1.0, min(1.0, norm_val))
                            updated = True

        if updated:
            self.publish_input(self._axes, self._buttons)

    def update_and_publish(self):
        # The base class might call this via a timer.
        # We publish the current state of our virtual joystick.
        self.publish_input(self._axes, self._buttons)

    def _word_to_num(self, word):
        # Clean the word
        word = word.strip().strip(',.?!')
        
        # Basic mapping for spoken numbers
        num_map = {
            'zero': 0.0, 'one': 1.0, 'two': 2.0, 'three': 3.0, 'four': 4.0,
            'five': 5.0, 'six': 6.0, 'seven': 7.0, 'eight': 8.0, 'nine': 9.0, 'ten': 10.0,
            'point': 0.5, # Special case for "point five" if transcribed oddly
        }
        
        try:
            return float(word)
        except ValueError:
            return num_map.get(word.lower())

def main(args=None):
    rclpy.init(args=args)
    node = VoiceNode()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()

if __name__ == '__main__':
    main()
